#include <iostream>
class Counter {
 int value_=0;
public:
 bool add(int n){if(n<0||n>100-value_)return false;value_+=n;return true;}
 int value()const{return value_;}
};
int main(){int n;if(!(std::cin>>n)||n<0||n>20){std::cout<<"invalid\n";return 0;}
 int amounts[20]{};for(int i=0;i<n;++i)if(!(std::cin>>amounts[i])){std::cout<<"invalid\n";return 0;}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 Counter c;int rejected=0;for(int i=0;i<n;++i)if(!c.add(amounts[i]))++rejected;
 std::cout<<c.value()<<' '<<rejected<<'\n';}
